begin;
create extension if not exists pgtap with schema extensions;
select plan(22);
select is((select count(*)::integer from cron.job where jobname='relay-task-schedules'),1,'One dispatcher installed');
select ok(not has_function_privilege('authenticated','public.dispatch_task_schedules()','EXECUTE'),'User cannot dispatch other owners work');
select ok(not has_function_privilege('anon','public.save_task_schedule(uuid,jsonb)','EXECUTE'),'Anonymous users cannot save');
select is(public.next_schedule_slot('Europe/London',array[1,2,3,4,5],60,540,1080,'2026-09-14 08:00Z'),'2026-09-14 09:00Z'::timestamptz,'Hourly slots are anchored to window start');
select is(public.next_schedule_slot('Europe/London',array[1,2,3,4,5],60,540,1080,'2026-09-14 16:00Z'),'2026-09-15 08:00Z'::timestamptz,'Window end is exclusive');
select is(public.next_schedule_slot('Europe/London',array[0],1440,90,120,'2026-03-28 23:00Z'),'2026-04-05 00:30Z'::timestamptz,'Nonexistent local DST time is skipped');
select is(public.next_schedule_slot('Europe/London',array[0],1440,90,120,'2026-10-24 23:00Z'),'2026-10-25 01:30Z'::timestamptz,'Repeated DST slot uses standard time once');
select is(public.next_schedule_slot('Europe/London',array[0],1440,90,120,'2026-10-25 01:30Z'),'2026-11-01 01:30Z'::timestamptz,'Repeated slot does not run again');
insert into auth.users(id) values('00000000-0000-4000-8000-000000000091'),('00000000-0000-4000-8000-000000000092');
insert into public.task_schedules(id,user_id,title,instructions,deliverable,timezone,weekdays,interval_minutes,start_minute,end_minute,enabled,next_due_at) values('00000000-0000-4000-8000-000000000093','00000000-0000-4000-8000-000000000091','Recurring test','Investigate','investigation','UTC',array[0,1,2,3,4,5,6],60,0,1440,true,now()-interval '3 days');
select is(public.dispatch_task_schedules(),1,'Outage coalesces to one task');
select is(public.dispatch_task_schedules(),0,'Repeated dispatch does not duplicate');
select is((select count(*)::integer from public.schedule_occurrences),1,'One occurrence exists');
select is((select deliverable from public.runs where task_id=(select task_id from public.schedule_occurrences)),'investigation','Run snapshots deliverable');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000092',true);
select throws_ok($$select public.run_task_schedule('00000000-0000-4000-8000-000000000093',gen_random_uuid())$$,'P0001','Schedule not found','Other owner cannot run schedule');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000091',true);
select is(public.run_task_schedule('00000000-0000-4000-8000-000000000093',gen_random_uuid()),null::uuid,'Run now respects active occurrence');
update public.runs set status='completed';
select public.run_task_schedule('00000000-0000-4000-8000-000000000093','00000000-0000-4000-8000-000000000094');
select public.run_task_schedule('00000000-0000-4000-8000-000000000093','00000000-0000-4000-8000-000000000094');
select is((select count(*)::integer from public.schedule_occurrences where trigger='manual'),1,'Run now request is idempotent');
select throws_ok($$insert into public.runs(task_id,user_id,attempt) select task_id,user_id,2 from public.schedule_occurrences where trigger='scheduled'$$,'P0001','This schedule already has an active run','Feedback cannot overlap another occurrence');
select public.save_task_schedule('00000000-0000-4000-8000-000000000093',(select to_jsonb(s)||'{"enabled":false}'::jsonb from public.task_schedules s));
select is((select count(*)::integer from public.runs where status='queued'),0,'Pause cancels unclaimed runs');
select is(public.dispatch_task_schedules(),0,'Paused schedules do not dispatch');
select is((select count(*)::integer from public.tasks where status='ready'),0,'Cancelled tasks no longer claim to be queued');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000092',true);
select is((select count(*)::integer from public.task_schedules),0,'RLS hides other owners schedules');
select is((select count(*)::integer from public.schedule_occurrences),0,'RLS hides other owners history');
select throws_ok($$select public.save_task_schedule('00000000-0000-4000-8000-000000000093','{}'::jsonb)$$,'P0001','Schedule not found','Another owner cannot edit');
reset role;
select * from finish();
rollback;
